p='src/CheckoutPricing.Application/CalculatePayableTotal.cs'
s=open(p).read()
old=s[s.index("    public int For(LoyaltyTier"):]
new='''    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9,
        };
        var bonus = subtotalCents switch
        {
            < 5000 => 0,
            < 20000 => 1,
            _ => 3,
        };
        var rate = Math.Min(baseRate + bonus, 10);

        return subtotalCents - (int)((long)subtotalCents * rate / 100);
    }
}
'''
open(p,'w').write(s.replace(old,new))
E
